function fr(name,dir,o={}){const f=figma.createFrame();f.name=name;f.layoutMode=dir||"VERTICAL";f.primaryAxisSizingMode="AUTO";f.counterAxisSizingMode="AUTO";f.fills=[];f.clipsContent=!!o.clip;f.itemSpacing=o.gap||0;const p=o.p||[0,0,0,0];[f.paddingTop,f.paddingRight,f.paddingBottom,f.paddingLeft]=p;f.primaryAxisAlignItems=o.main||"MIN";f.counterAxisAlignItems=o.cross||"MIN";return f}
